// DTO: bentuk data yang DITERIMA API (validasi terpusat)
import { IsString, IsBoolean, IsOptional, MaxLength, MinLength } from 'class-validator';

export class BuatCatatanDto {
  @IsString()
  @MinLength(3, { message: 'judul minimal 3 karakter' })
  @MaxLength(200)
  judul: string;

  @IsOptional()
  @IsBoolean()
  selesai?: boolean;
}

